-- county_context: int_spine_county_context pivoted to one row per spine key (design: p3c/design.md section 2).

with

spine as (
    select
        hospital.spine_key,
        (hospital.county_source = 'pos_own' and hospital.planning_region_fips is null) is true as county_family_eligible,
        (hospital.zip_code is not null and hospital.zip_code = left(own_snapshot.zip_code, 5)) is true as ruca_zip_eligible,
        (hospital.window_start::timestamp) at time zone 'UTC' as event_timestamp
    from {{ ref('int_hospital_spine') }} as hospital
    left join {{ ref('fct_pos_snapshot') }} as own_snapshot
        on
            hospital.ccn = own_snapshot.ccn
            and hospital.pos_period_end = own_snapshot.period_end
),

measures as (
    select
        measures.spine_key,
        measures.value_number,
        spine.county_family_eligible,
        spine.ruca_zip_eligible,
        measures.measure_source || '|' || measures.measure_control || '|' || measures.field as pivot_key
    from {{ ref('int_spine_county_context') }} as measures
    inner join spine on measures.spine_key = spine.spine_key
),

